from urllib.parse import parse_qsl, urlencode, urlsplit, urlunsplit

_PARAMS = {"api_key", "key", "token", "access_token", "refresh_token", "client_secret", "signature", "password"}
_KEYS = {"password", "secret", "client_secret", "token", "access_token", "refresh_token", "api_key"}


def redact_headers(headers):
    out = {}
    for name, value in headers.items():
        lower = name.lower()
        if lower in ("authorization", "proxy-authorization"):
            scheme, space, _rest = value.partition(" ")
            out[name] = f"{scheme} REDACTED" if space else "REDACTED"
        elif lower in ("cookie", "set-cookie") or (lower.startswith("x-") and (lower.endswith("-key") or lower.endswith("-token"))):
            out[name] = "REDACTED"
        else:
            out[name] = value
    return out


def redact_url(url):
    parts = urlsplit(url)
    changed = False
    netloc = parts.netloc
    if "@" in netloc:
        userinfo, host = netloc.rsplit("@", 1)
        if ":" in userinfo:
            user = userinfo.split(":", 1)[0]
            netloc = f"{user}:REDACTED@{host}"
            changed = True
    pairs = parse_qsl(parts.query, keep_blank_values=True)
    redacted = []
    for name, value in pairs:
        if name.lower() in _PARAMS:
            redacted.append((name, "REDACTED"))
            changed = True
        else:
            redacted.append((name, value))
    if not changed:
        return url
    query = urlencode(redacted) if any(name.lower() in _PARAMS for name, _ in pairs) else parts.query
    return urlunsplit((parts.scheme, netloc, parts.path, query, parts.fragment))


def redact_json(value):
    if isinstance(value, dict):
        return {k: ("REDACTED" if isinstance(k, str) and k.lower() in _KEYS else redact_json(v)) for k, v in value.items()}
    if isinstance(value, list):
        return [redact_json(v) for v in value]
    return value

