@test("headers")
def _():
    h = {"Authorization": "Bearer abc.def", "Accept": "application/json", "X-Api-Key": "k1", "cookie": "s=1", "X-Request-Id": "r1"}
    check_eq(redact_headers(h), {"Authorization": "Bearer REDACTED", "Accept": "application/json", "X-Api-Key": "REDACTED", "cookie": "REDACTED", "X-Request-Id": "r1"})
    check_eq(list(redact_headers(h)), list(h))
    check_eq(redact_headers({"authorization": "rawtoken"}), {"authorization": "REDACTED"})
    check_eq(redact_headers({"Proxy-Authorization": "Basic dXNlcjpwYXNz"}), {"Proxy-Authorization": "Basic REDACTED"})
    check_eq(redact_headers({"X-Auth-Token": "t", "Set-Cookie": "id=9", "X-Keyboard": "qwerty"}), {"X-Auth-Token": "REDACTED", "Set-Cookie": "REDACTED", "X-Keyboard": "qwerty"})
    check_eq(h["Authorization"], "Bearer abc.def")

@test("URLs")
def _():
    check_eq(redact_url("https://api.example.com/v1/books?limit=5&api_key=sk_live_abc"), "https://api.example.com/v1/books?limit=5&api_key=REDACTED")
    check_eq(redact_url("https://h/x?Token=1&q=a+b&empty=&SIGNATURE=zz#frag"), "https://h/x?Token=REDACTED&q=a+b&empty=&SIGNATURE=REDACTED#frag")
    check_eq(redact_url("https://h/x?q=a%20b&limit=5"), "https://h/x?q=a%20b&limit=5")
    check_eq(redact_url("https://h/x"), "https://h/x")
    check_eq(redact_url("https://bob:hunter2@h.example/x?y=1"), "https://bob:REDACTED@h.example/x?y=1")
    check_eq(redact_url("https://bob@h.example/x"), "https://bob@h.example/x")

@test("JSON at any depth")
def _():
    doc = {"user": "ana", "Password": "pw", "nested": {"refresh_token": "r", "items": [{"api_key": "k", "n": 1}, 5]}, "token_count": 3}
    check_eq(redact_json(doc), {"user": "ana", "Password": "REDACTED", "nested": {"refresh_token": "REDACTED", "items": [{"api_key": "REDACTED", "n": 1}, 5]}, "token_count": 3})
    check_eq(doc["Password"], "pw")
    check_eq(redact_json([{"secret": {"deep": 1}}]), [{"secret": "REDACTED"}])
    check_eq(redact_json("token"), "token")
    check_eq(redact_json(None), None)

@test("no secret survives")
def _():
    secret = "sk_live_NEVER_LOG_ME"
    lines = [
        str(redact_headers({"Authorization": f"Bearer {secret}"})),
        redact_url(f"https://h/x?access_token={secret}"),
        str(redact_json({"client_secret": secret, "list": [{"token": secret}]})),
    ]
    for line in lines:
        check(secret not in line, f"secret leaked in {line}")

